#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const float TEMP_LIMIT_C = 50.0f;
const int SMOKE_LIMIT = 400;
int previousLevel = -1;
bool sounding = false;
unsigned long lastBeep = 0;

void setup() {
  pinMode(A0, INPUT);
  pinMode(A1, INPUT);
  pinMode(2, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  pinMode(12, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(12, LOW);
  digitalWrite(13, LOW);
  noTone(6);
  Serial.begin(9600);
  display.setBrightness(7);
}

void loop() {
  unsigned long now = millis();
  int smoke = analogRead(A0);
  float temperature = analogRead(A1) * (500.0f / 1023.0f);
  bool flame = digitalRead(2) == LOW;
  int exceeded = (temperature > TEMP_LIMIT_C ? 1 : 0)
               + (smoke > SMOKE_LIMIT ? 1 : 0);
  int level = (flame || exceeded >= 2) ? 2 : (exceeded == 1 ? 1 : 0);
  bool changed = level != previousLevel;

  digitalWrite(12, level == 0 ? HIGH : LOW);
  digitalWrite(13, level != 0 ? HIGH : LOW);
  int key = constrain((int)(temperature + 0.5f), 0, 999);
  display.showNumberDec(level * 1000 + key, true);

  if (level == 2) {
    if (changed) {
      sounding = true;
      tone(6, 2000);
      lastBeep = now;
      Serial.println("fire alert");
    } else if (now - lastBeep >= 500UL) {
      lastBeep = now;
      sounding = !sounding;
      if (sounding) tone(6, 2000);
      else noTone(6);
    }
  } else {
    noTone(6);
    sounding = false;
  }
  previousLevel = level;
  delay(20);
}
